def is_fig(v):
    return isinstance(v,(int,float)) and not isinstance(v,bool) and math.isfinite(v)

for folder in ("data/packs/ryde-synth-v1/disputes", "data/packs/organiser-style-v1/disputes"):
    print("==", folder)
    for cid in ("RD-0101","RD-0102","RD-0103","RD-0104","RD-0105","RD-0106","RD-0107","RD-0108","RD-0109"):
        p = Path(folder) / (cid + ".json")
        if not p.exists():
            print(cid, "MISSING"); continue
        pack = build_evidence_pack(load_dispute(p))
        f = pack.fare
        route = pack.route
        proofs = [0.0]
        if f is not None:
            if is_fig(f.difference_sgd):
                proofs.append(max(f.difference_sgd, 0.0))
            if f.breakdown_consistent is False and is_fig(f.charged_sgd) and is_fig(f.component_sum_sgd):
                proofs.append(max(f.charged_sgd - f.component_sum_sgd, 0.0))
            material = False
            if route is not None:
                km, pct = route.deviation_km, route.deviation_pct
                if is_fig(km) and km >= 5.0:
                    material = True
                elif is_fig(km) and is_fig(pct) and pct >= 20.0 and km >= 1.0:
                    material = True
            if material and is_fig(f.charged_sgd) and is_fig(f.recomputed_estimated_route_sgd):
                proofs.append(max(f.charged_sgd - f.recomputed_estimated_route_sgd, 0.0))
        print(cid, "provable=%.2f" % round(max(proofs),2),
